export const defaults = Object.freeze({recipient:'亲爱的你',sender:'一个惦记你的人',title:'今晚，\n月光只为你停留。',intro:'有些祝福，想慢慢说给你听。',letter:'今天，先把忙碌留在门外。\n\n这一年的你，也许走过一些不容易的路，也悄悄完成了许多了不起的小事。那些努力、善意和勇敢，都值得被好好看见。\n\n所以，今晚只想认真地对你说：\n谢谢你，长成了现在的自己。\n\n新的一岁，不必急着成为谁期待的样子。愿你慢慢走，尽情爱，也记得把一份温柔留给自己。',ending:'愿你有热爱，有回应。\n愿新的一岁，每一步都更靠近喜欢的自己。',tone:'moon',particles:true});
const limits={recipient:16,sender:24,title:50,intro:70,letter:600,ending:120};
export function normalize(value={}) { const result={...defaults}; if (!value || typeof value!=='object'||Array.isArray(value)) return result; for(const [key,max] of Object.entries(limits))if(typeof value[key]==='string'&&value[key].trim())result[key]=value[key].trim().slice(0,max); result.tone=value.tone==='amber'?'amber':'moon';result.particles=typeof value.particles==='boolean'?value.particles:true;return result; }
export function encodeConfig(value){const bytes=new TextEncoder().encode(JSON.stringify(normalize(value)));return btoa(Array.from(bytes,b=>String.fromCharCode(b)).join('')).replaceAll('+','-').replaceAll('/','_').replaceAll('=','');}
export function decodeConfig(hash){if(!hash.startsWith('#letter='))return null;const encoded=hash.slice(8);if(encoded.length>18000)throw Error('链接内容太长');const base=encoded.replaceAll('-','+').replaceAll('_','/');const data=JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(Uint8Array.from(atob(base),c=>c.charCodeAt(0))));if(!data||typeof data!=='object'||Array.isArray(data))throw Error('链接格式有误');return normalize(data);}
